yakit.AutoInitYakit()

# Input your code!

// 协议
schemaHttp := "http://"
schemaHttps := "https://"

// 请求包超时
timeout := http.timeout(cli.Int("timeout"));
// ua头
ua := http.useragent(cli.String("user_agent"))
accept := http.header("Accept", "text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,image/apng,*/*;q=0.8,application/signed-exchange;v=b3;q=0.7")
// ae := http.header("Accept-Encoding", "gzip, deflate, br")
ae := http.header("Accept-Encoding", "")
al := http.header("Accept-Language", "en-US,zh;q=0.9")
scu := http.header("sec-ch-ua", `"Chromium";v="112", "Google Chrome";v="112", "Not:A-Brand";v="99"`)

// 表格数据
yakit.EnableTable("存活URL信息表", ["URL", "标题", "状态码", "响应包"])
// 增加表格数据
outputTable = func(url, title, code, packet) {
    data = make(map[string]var)
    data["URL"] = url
    data["标题"] = title
    data["响应包"] = packet
    data["状态码"] = code
    yakit.TableData("存活URL信息表", data)
}

// 发送请求 默认GET
func sendRequest(url) {
    req, err = http.NewRequest("GET", url, ua, timeout, accept, ae, al, scu)
    if (err != nil) {
        return nil, false
    }

    rsp, err := http.Do(req)
    return rsp, true
}

// 探测url
func detectUrls(urlArr) {
    // 遍历url列表
    for i, v := range urlArr {
        // 日志开关
        if cli.Bool("showLog") {
            printf("%d\r", i+1)
        }

        // 拼接协议
        url := schemaHttps + v
        rsp, err := sendRequest(url)
        if (!err || rsp == nil) {
            // 尝试http协议
            url = schemaHttp + v
            if cli.Bool("showLog") {
                println("[*_*] try other: ", url)
            }

            rsp, err = sendRequest(url)
            if (!err || rsp == nil) {
                continue
            }

        }

        // 导出响应头
        headerBytes, err := http.dumphead(rsp)
        // 导出响应体
        packetBytes, err := http.dump(rsp)
        packetHeader := string(headerBytes)
        packet := string(packetBytes)

        // 匹配title
        title := "-"
        res := re.FindSubmatchAll(packet, `<title.*?>(.*?)</title>`)
        // println(res)
        if (len(res) > 0 && len(res[0]) > 1) {
            title = res[0][1]
        }

        // 匹配状态码
        code = re.Find(packetHeader, `\b\d{3}\b`)

        // 填充数据
        outputTable(url, title, code, packetHeader)
        printf("====================================\n")
        printf("[+_+] %s\n", url)
        // http.show(req)
        // http.show(rsp)
        printf("====================================\n\n")
        // raw, err := io.ReadAll(rsp.Body)
        // if (err != nil) {
        //     continue
        // }
        // println(string(raw))
    }
}

// 入口
func main() {
    urls := cli.String("urls")
    urls = str.TrimSpace(urls)
    if (urls == "") {
        return
    }

    // 换行符切割文本
    urlArr := str.Split(urls, "\n")
    for (i := 0; i < len(urlArr); i++) {
        // 移除带有协议字符
        if str.Contains(urlArr[i], schemaHttp) {
            urlArr[i] = str.ReplaceAll(urlArr[i], schemaHttp, "")
        } else if str.Contains(urlArr[i], schemaHttps) {
            urlArr[i] = str.ReplaceAll(urlArr[i], schemaHttps, "")
        }

    }

    detectUrls(urlArr)
}

main()
